import sys
import json
import os

def main():
    if len(sys.argv) < 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    reports_path = os.path.join(packet_dir, 'fda_enforcement_reports.json')
    reports_data = {}
    if os.path.exists(reports_path):
        with open(reports_path, 'r', encoding='utf-8') as f:
            reports_data = json.load(f)

    records_by_entity = {}
    for record in reports_data.get('results', []):
        entity = record.get('recall_number')
        if entity:
            records_by_entity.setdefault(entity, []).append(record)

    fact_to_field = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date"
    }

    def format_date(d):
        if not d or not str(d).strip():
            return "ABSENT"
        d = str(d).strip()
        if len(d) == 8 and d.isdigit():
            return f"{d[:4]}-{d[4:6]}-{d[6:]}"
        return d

    results = {}
    for pair in manifest.get('pairs', []):
        if '::' not in pair:
            continue
        rule_id, entity = pair.split('::', 1)
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_result = {}
        records = records_by_entity.get(entity, [])

        for fact in facts:
            field = fact_to_field.get(fact)
            if not field:
                pair_result[fact] = "ABSENT"
                continue

            if not records:
                pair_result[fact] = "ABSENT"
                continue

            values = set()
            for record in records:
                val = record.get(field, "")
                formatted = format_date(val)
                values.add(formatted)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                val = values.pop()
                if val == "ABSENT":
                    pair_result[fact] = "ABSENT"
                else:
                    pair_result[fact] = [val, "fda_enforcement_reports"]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()

