import sys
import json
import os

def format_date(d):
    if len(d) == 8 and d.isdigit():
        return f"{d[:4]}-{d[4:6]}-{d[6:]}"
    return d

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_file = os.path.join(packet_dir, 'fda_enforcement_reports.json')
    if os.path.exists(fda_file):
        with open(fda_file, 'r') as f:
            fda_data = json.load(f)
    else:
        fda_data = {"results": []}

    recalls = {}
    for result in fda_data.get('results', []):
        recall_number = result.get('recall_number')
        if not recall_number:
            continue
        if recall_number not in recalls:
            recalls[recall_number] = []
        recalls[recall_number].append(result)

    output = {}
    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::', 1)
        facts = manifest.get('facts', {}).get(rule_id, [])

        output[pair] = {}

        entity_records = recalls.get(entity, [])

        for fact in facts:
            if fact == "initiation date":
                field = "recall_initiation_date"
            elif fact == "classification date":
                field = "center_classification_date"
            elif fact == "termination date":
                field = "termination_date"
            else:
                continue

            values = set()
            for record in entity_records:
                val = record.get(field)
                if val is None:
                    val = ""
                val = str(val).strip()
                values.add(val)

            if not values or (len(values) == 1 and "" in values):
                output[pair][fact] = "ABSENT"
            elif len(values) > 1:
                output[pair][fact] = "CONFLICT"
            else:
                val = values.pop()
                output[pair][fact] = [format_date(val), "fda_enforcement_reports"]

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

