import sys
import json
import os

def format_date(d):
    if not d:
        return None
    d = d.strip()
    if len(d) == 8 and d.isdigit():
        return f"{d[:4]}-{d[4:6]}-{d[6:]}"
    return d

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_file = os.path.join(packet_dir, 'fda_enforcement_reports.json')
    fda_data = {}
    if os.path.exists(fda_file):
        with open(fda_file, 'r') as f:
            data = json.load(f)
            for result in data.get('results', []):
                recall_number = result.get('recall_number')
                if recall_number:
                    if recall_number not in fda_data:
                        fda_data[recall_number] = []
                    fda_data[recall_number].append(result)

    output = {}
    for pair in manifest['pairs']:
        rule_id, entity = pair.split('::')
        facts = manifest['facts'][rule_id]

        pair_output = {}
        for fact in facts:
            values = set()

            records = fda_data.get(entity, [])
            for record in records:
                val = None
                if fact == "initiation date":
                    val = record.get("recall_initiation_date")
                elif fact == "classification date":
                    val = record.get("center_classification_date")
                elif fact == "termination date":
                    val = record.get("termination_date")

                if val:
                    formatted_val = format_date(val)
                    if formatted_val:
                        values.add((formatted_val, "fda_enforcement_reports"))

            if len(values) == 0:
                pair_output[fact] = "ABSENT"
            elif len(values) == 1:
                pair_output[fact] = list(list(values)[0])
            else:
                val_set = set(v[0] for v in values)
                if len(val_set) == 1:
                    pair_output[fact] = list(list(values)[0])
                else:
                    pair_output[fact] = "CONFLICT"

        output[pair] = pair_output

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

