import sys
import json
import os

def format_date(date_str):
    if len(date_str) == 8 and date_str.isdigit():
        return f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:]}"
    return date_str

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_file = os.path.join(packet_dir, 'fda_enforcement_reports.json')
    with open(fda_file, 'r') as f:
        fda_data = json.load(f)

    records_by_recall = {}
    for record in fda_data.get('results', []):
        recall_number = record.get('recall_number')
        if not recall_number:
            continue
        if recall_number not in records_by_recall:
            records_by_recall[recall_number] = []
        records_by_recall[recall_number].append(record)

    output = {}

    for pair in manifest['pairs']:
        rule_id, entity = pair.split('::')
        facts = manifest['facts'][rule_id]

        output[pair] = {}
        records = records_by_recall.get(entity, [])

        for fact in facts:
            if fact == "initiation date":
                field = "recall_initiation_date"
            elif fact == "classification date":
                field = "center_classification_date"
            elif fact == "termination date":
                field = "termination_date"
            else:
                continue

            values = set()
            for record in records:
                val = record.get(field, "")
                if val is None:
                    val = ""
                values.add(str(val).strip())

            if not values:
                output[pair][fact] = "ABSENT"
            elif len(values) > 1:
                output[pair][fact] = "CONFLICT"
            else:
                val = values.pop()
                if not val:
                    output[pair][fact] = "ABSENT"
                else:
                    output[pair][fact] = [format_date(val), "fda_enforcement_reports"]

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

